import{_ as o,a0 as l,w as n,s as c,ao as r,I as a,x as s,a1 as t,A as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何使用特殊權限：setuid、setgid 和 sticky 位 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用特殊權限：setuid、setgid 和 sticky 位 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用特殊權限：setuid、setgid 和 sticky 位 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用特殊權限：setuid、setgid 和 sticky 位 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171120 How to use special permissions- the setuid, setgid and sticky bits","title":"如何使用特殊權限：setuid、setgid 和 sticky 位","tag":"201802","desc":""},"relativePath":"201802/20171120 How to use special permissions- the setuid, setgid and sticky bits.md","filePath":"[post].md"}'),p={name:"201802/20171120 How to use special permissions- the setuid, setgid and sticky bits.md"};function h(g,e,u,k,b,f){const i=l("Link");return n(),c("div",null,[e[13]||(e[13]=r(`<h1 id="如何使用特殊權限-setuid、setgid-和-sticky-位" tabindex="-1">如何使用特殊權限：setuid、setgid 和 sticky 位 <a class="header-anchor" href="#如何使用特殊權限-setuid、setgid-和-sticky-位" aria-label="Permalink to “如何使用特殊權限：setuid、setgid 和 sticky 位”">​</a></h1><h3 id="目標" tabindex="-1">目標 <a class="header-anchor" href="#目標" aria-label="Permalink to “目標”">​</a></h3><p>瞭解特殊權限的工作原理，以及如何識別和設置它們。</p><h3 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to “要求”">​</a></h3><ul><li>瞭解標準的 Unix / Linux 權限系統</li></ul><h3 id="難度" tabindex="-1">難度 <a class="header-anchor" href="#難度" aria-label="Permalink to “難度”">​</a></h3><p>簡單</p><h3 id="約定" tabindex="-1">約定 <a class="header-anchor" href="#約定" aria-label="Permalink to “約定”">​</a></h3><ul><li><code>#</code> - 要求直接以 root 用户或使用 <code>sudo</code> 命令執行指定的命令</li><li><code>$</code> - 用普通的非特權用户來執行指定的命令</li></ul><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p>通常，在類 Unix 操作系統上，文件和目錄的所有權是基於文件創建者的默認 <code>uid</code>（user-id）和 <code>gid</code>（group-id）的。啓動一個進程時也是同樣的情況：它以啓動它的用户的 <code>uid</code> 和 <code>gid</code> 運行，並具有相應的權限。這種行為可以通過使用特殊的權限進行改變。</p><h3 id="setuid-位" tabindex="-1">setuid 位 <a class="header-anchor" href="#setuid-位" aria-label="Permalink to “setuid 位”">​</a></h3><p>當使用 setuid （設置用户 ID）位時，之前描述的行為會有所變化，所以當一個可執行文件啓動時，它不會以啓動它的用户的權限運行，而是<strong>以該文件所有者的權限運行</strong>。所以，如果在一個可執行文件上設置了 setuid 位，並且該文件由 root 擁有，當一個普通用户啓動它時，它將以 root 權限運行。顯然，如果 setuid 位使用不當的話，會帶來潛在的安全風險。</p><p>使用 setuid 權限的可執行文件的例子是 <code>passwd</code>，我們可以使用該程序更改登錄密碼。我們可以通過使用 <code>ls</code> 命令來驗證：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -l /bin/passwd</span></span>
<span class="line"><span>-rwsr-xr-x. 1 root root 27768 Feb 11 2017 /bin/passwd</span></span></code></pre></div><p>如何識別 <code>setuid</code> 位呢？相信您在上面命令的輸出已經注意到，<code>setuid</code> 位是用 <code>s</code> 來表示的，代替了可執行位的 <code>x</code>。小寫的 <code>s</code> 意味着可執行位已經被設置，否則你會看到一個大寫的 <code>S</code>。大寫的 <code>S</code> 發生於當設置了 <code>setuid</code> 或 <code>setgid</code> 位、但沒有設置可執行位 <code>x</code> 時。它用於提醒用户這個矛盾的設置：如果可執行位未設置，則 <code>setuid</code> 和 <code>setgid</code> 位均不起作用。setuid 位對目錄沒有影響。</p><h3 id="setgid-位" tabindex="-1">setgid 位 <a class="header-anchor" href="#setgid-位" aria-label="Permalink to “setgid 位”">​</a></h3><p>與 <code>setuid</code> 位不同，<code>setgid</code> （設置組 ID）位對文件和目錄都有影響。在第一個例子中，具有 <code>setgid</code> 位設置的文件在執行時，不是以啓動它的用户所屬組的權限運行，而是<strong>以擁有該文件的組運行</strong>。換句話説，進程的 <code>gid</code> 與文件的 <code>gid</code> 相同。</p><p>當在一個目錄上使用時，<code>setgid</code> 位與一般的行為不同，它使得在所述目錄內創建的文件，不屬於創建者所屬的組，而是屬於父目錄所屬的組。這個功能通常用於文件共享（目錄所屬組中的所有用户都可以修改文件）。就像 setuid 一樣，setgid 位很容易識別（我們用 test 目錄舉例）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -ld test</span></span>
<span class="line"><span>drwxrwsr-x. 2 egdoc egdoc 4096 Nov 1 17:25 test</span></span></code></pre></div><p>這次 <code>s</code> 出現在組權限的可執行位上。</p><h3 id="sticky-位" tabindex="-1">sticky 位 <a class="header-anchor" href="#sticky-位" aria-label="Permalink to “sticky 位”">​</a></h3><p>sticky （粘連）位的工作方式有所不同：它對文件沒有影響，但當它在目錄上使用時，所述目錄中的所有文件只能由其所有者刪除或移動。一個典型的例子是 <code>/tmp</code> 目錄，通常系統中的所有用户都對這個目錄有寫權限。所以，設置 sticky 位使用户不能刪除其他用户的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -ld /tmp</span></span>
<span class="line"><span>drwxrwxrwt. 14 root root 300 Nov 1 16:48 /tmp</span></span></code></pre></div><p>在上面的例子中，目錄所有者、組和其他用户對該目錄具有完全的權限（讀、寫和執行）。sticky 位在可執行位上用 <code>t</code> 來標識。同樣，小寫的 <code>t</code> 表示可執行權限 <code>x</code>也被設置了，否則你會看到一個大寫字母 <code>T</code>。</p><h3 id="如何設置特殊權限位" tabindex="-1">如何設置特殊權限位 <a class="header-anchor" href="#如何設置特殊權限位" aria-label="Permalink to “如何設置特殊權限位”">​</a></h3><p>就像普通的權限一樣，特殊權限位可以用 <code>chmod</code> 命令設置，使用數字或者 <code>ugo/rwx</code> 格式。在前一種情況下，<code>setuid</code>、<code>setgid</code> 和 <code>sticky</code> 位分別由數值 4、2 和 1 表示。例如，如果我們要在目錄上設置 <code>setgid</code> 位，我們可以運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod 2775 test</span></span></code></pre></div><p>通過這個命令，我們在目錄上設置了 <code>setgid</code> 位（由四個數字中的第一個數字標識），並給它的所有者和該目錄所屬組的所有用户賦予全部權限，對其他用户賦予讀和執行的權限（目錄上的執行位意味着用户可以 <code>cd</code> 進入該目錄或使用 <code>ls</code> 列出其內容）。</p><p>另一種設置特殊權限位的方法是使用 <code>ugo/rwx</code> 語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod g+s test</span></span></code></pre></div><p>要將 <code>setuid</code> 位應用於一個文件，我們可以運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod u+s file</span></span></code></pre></div><p>要設置 sticky 位，可運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod o+t test</span></span></code></pre></div><p>在某些情況下，使用特殊權限會非常有用。但如果使用不當，可能會引入嚴重的漏洞，因此使用之前請三思。</p><hr>`,37)),a("p",null,[e[1]||(e[1]=s("via: ",-1)),t(i,{href:"https://linuxconfig.org/how-to-use-special-permissions-the-setuid-setgid-and-sticky-bits"},{default:d(()=>[...e[0]||(e[0]=[s("https://linuxconfig.org/how-to-use-special-permissions-the-setuid-setgid-and-sticky-bits",-1)])]),_:1})]),a("p",null,[e[5]||(e[5]=s("作者：",-1)),t(i,{href:"https://linuxconfig.org"},{default:d(()=>[...e[2]||(e[2]=[s("Egidio Docile",-1)])]),_:1}),e[6]||(e[6]=s(" 譯者：",-1)),t(i,{href:"https://github.com/jessie-pang"},{default:d(()=>[...e[3]||(e[3]=[s("jessie-pang",-1)])]),_:1}),e[7]||(e[7]=s(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:d(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),a("p",null,[e[10]||(e[10]=s("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:d(()=>[...e[9]||(e[9]=[s("Linux中國",-1)])]),_:1}),e[12]||(e[12]=s(" 榮譽推出",-1))])])}const C=o(p,[["render",h]]);export{y as __pageData,C as default};
